!function(){"use strict";var shell=document.querySelector("[data-shell]");if(shell){document.querySelectorAll("[data-shell-drawer]").forEach((function(btn){btn.addEventListener("click",(function(e){e.stopPropagation(),shell.classList.toggle("is-drawer-l")}))})),shell.querySelectorAll("[data-shell-drawer-close]").forEach((function(btn){btn.addEventListener("click",closeDrawer)}));var backdrop=shell.querySelector("[data-shell-backdrop]");backdrop&&backdrop.addEventListener("click",closeDrawer),window.addEventListener("resize",(function(){window.innerWidth>767&&closeDrawer()}))}function closeDrawer(){shell.classList.remove("is-drawer-l")}}();
